/* @lc app=leetcode id=3896 lang=kotlin */ class Solution { fun minOperations(nums: IntArray): Int = BooleanArray(100200) { it >= 2 }.also { s -> (2..316).forEach { i -> if (s[i]) (i * i until 100200 step i).forEach { s[it] = false } } }.let { pr -> nums.indices.sumOf { i -> if (i % 2 == 0) generateSequence(nums[i]) { it + 1 }.first { pr[it] } - nums[i] else generateSequence(nums[i]) { it + 1 }.first { !pr[it] } - nums[i] } } }